from __future__ import annotations
from typing import Any
from .models import stable_hash


def compile_paid_campaign_architecture(project_id:str, target:dict[str,Any], assets:list[dict[str,Any]], product_truth:dict[str,Any], economics:dict[str,Any]|None=None, ads:dict[str,Any]|None=None, explicit:list[dict[str,Any]]|None=None, content_objects:list[dict[str,Any]]|None=None)->dict[str,Any]:
    """Paid is an independent campaign system, not a resized PDP image."""
    jobs=list(explicit or [])
    if not jobs:
        paid=[a for a in assets if str(a.get('family')).upper()=='PAID' or str(a.get('surface')).upper()=='PAID_AD']
        for a in paid:
            jobs.append({'source_asset_id':a.get('asset_id'),'shopper_question':a.get('consumer_question'),'decision_intent':a.get('decision_intent'),'objective':'Move a qualified target shopper from the named tension to the next commerce action.','audience_state':a.get('entry_state'),'target_belief':a.get('belief_target'),'offer':None,'proof':a.get('incremental_information'),'landing_handoff':a.get('handoff') or 'PDP_OR_LANDING_SURFACE'})
        if not jobs and any(str(o.get('family')).upper()=='PAID' for o in (content_objects or [])):
            seed=next((a for a in assets if str(a.get('race_stage')).upper()=='COMMUNICATION'), assets[0] if assets else {})
            jobs.append({'source_asset_id':seed.get('asset_id'),'shopper_question':seed.get('consumer_question') or 'Why should a qualified shopper care now?','decision_intent':seed.get('decision_intent') or 'RELEVANCE','objective':'Acquire qualified traffic with a distinct paid-native concept that hands off to the commerce surface.','audience_state':seed.get('entry_state'),'target_belief':seed.get('belief_target'),'offer':None,'proof':seed.get('incremental_information'),'landing_handoff':'PDP_OR_LANDING_SURFACE'})
    campaigns=[]
    for i,j in enumerate(jobs):
        cid='CMP-'+stable_hash([project_id,target.get('target_id'),j,i])[:10].upper()
        q=j.get('shopper_question') or 'Why should this shopper care now?'
        intent=j.get('decision_intent') or 'DECISION_SUPPORT'
        concepts=[
            {
                'concept_id':cid+'-A','route':'TENSION_TO_PROOF','hook':q,'composition':'Lead with the buyer tension/question, then reveal one product-specific proof relationship; product is evidence, not decoration.','media_logic':'Fast first-frame comprehension followed by one proof beat and one handoff.','test_variable':'buyer tension / proof framing'
            },
            {
                'concept_id':cid+'-B','route':'PRODUCT_MECHANISM_TO_OUTCOME','hook':'Show the product-specific mechanism or use moment before explaining the benefit.','composition':'Mechanism/action-led opening with a materially different spatial grammar from Concept A; copy labels the visible mechanism rather than repeating the headline.','media_logic':'Visual-first demonstration or feature relationship, then outcome/value, then handoff.','test_variable':'mechanism-first / outcome-first framing'
            }
        ]
        campaigns.append({
            'campaign_id':cid,'objective':j.get('objective'),'audience_segment':j.get('audience_segment') or target.get('audience') or 'Current target audience evidence',
            'audience_state':j.get('audience_state'),'consumer_tension':q,'decision_intent':intent,'target_belief':j.get('target_belief'),
            'offer':j.get('offer'),'proof_mechanism':j.get('proof'),'landing_handoff':j.get('landing_handoff') or 'PDP_OR_LANDING_SURFACE',
            'creative_concepts':concepts,'variant_hypotheses':[{'variant':'A','hypothesis':'Question/tension-first increases qualified attention when the barrier is not yet articulated.'},{'variant':'B','hypothesis':'Mechanism/action-first increases comprehension when the product difference is visually demonstrable.'}],
            'measurement':{'primary':'CTR_OR_QUALIFIED_CLICK_BY_OBJECTIVE','secondary':['CVR','CPA','contribution'],'economics_context':(economics or {}).get('status') or 'USE_CURRENT_OFFER_ECONOMICS','diagnostic_context':(ads or {}).get('status') or 'NO_AD_PERFORMANCE_INPUT'},
            'source_asset_id':j.get('source_asset_id')
        })
    return {'status':'COMPILED' if campaigns else 'NOT_REQUIRED','dynamic_count':len(campaigns),'campaigns':campaigns,'principle':'Paid creative has its own objective, tension, offer/proof and landing handoff; it is never generated by simply resizing a PDP or Gallery asset.'}
